#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill for Parity 2.5 Staging Verification.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env.staging}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  This wizard sets up and verifies the Cloudflare Staging environment\n' "$DIM"
  printf '  (D1, R2, Migrations, Secrets & Smoke Tests) for the Auditor Closure Gate.\n'
  printf '  Stop any time with Ctrl-C and re-run later; progress is saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Staging Setup & Verification Ready%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "saved configuration to $ENV_FILE: ${WRITTEN_ENV[*]}"
  printf '\n'
  say "Next step: copy the generated staging output to provide to your auditor."
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Cloudflare Staging Setup & Verification
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

banner "Cloudflare Staging Setup & Verification Wizard"

# ── Stage 1: Cloudflare Authentication ────────────────────────────────────
stage "Cloudflare Authentication"
say "We will verify your Cloudflare authentication for Wrangler and Cloudflare CLI (cf)."

step "1. Checking Wrangler authentication..."
if npx wrangler whoami >/dev/null 2>&1; then
  step "✓ Wrangler authenticated!"
else
  step "Opening Cloudflare login via Wrangler CLI..."
  npx wrangler login
fi

step "2. Checking Cloudflare CLI (cf) authentication..."
if npx cf auth whoami >/dev/null 2>&1; then
  step "✓ Cloudflare CLI (cf) authenticated!"
else
  step "Opening Cloudflare login via cf CLI..."
  npx cf auth login
fi
pause "Press Enter once authenticated with Cloudflare"

# ── Stage 2: Staging D1 Database ──────────────────────────────────────────
stage "D1 Database Provisioning"
say "Let's ensure the staging D1 database exists."
step "Checking or creating D1 database: 'parity-db-staging'..."
note "Run command: npx wrangler d1 create parity-db-staging"
ask D1_DATABASE_ID "Paste your staging D1 Database ID (UUID):"
write_env D1_DATABASE_ID "$D1_DATABASE_ID"

# ── Stage 3: Staging R2 Bucket ────────────────────────────────────────────
stage "R2 Storage Bucket Provisioning"
say "Let's ensure the staging R2 bucket exists."
step "Checking or creating R2 bucket: 'parity-photos-staging'..."
if confirm "Do you need to create the 'parity-photos-staging' bucket now?"; then
  npx wrangler r2 bucket create parity-photos-staging || true
fi
step "Bucket 'parity-photos-staging' verified."
write_env R2_BUCKET_NAME "parity-photos-staging"

# ── Stage 4: Run Migrations on Staging D1 ─────────────────────────────────
stage "D1 Migrations Apply (0001 -> 0002)"
say "Applying schema migrations to the staging D1 database."

# Ensure wrangler.jsonc is configured with staging IDs
cat <<EOF > wrangler.jsonc
{
  "\$schema": "node_modules/wrangler/config-schema.json",
  "name": "parity-app-staging",
  "main": "src/worker.ts",
  "compatibility_date": "2026-10-17",
  "compatibility_flags": ["nodejs_compat"],
  "d1_databases": [
    {
      "binding": "DB",
      "database_name": "parity-db-staging",
      "database_id": "${D1_DATABASE_ID}",
      "migrations_dir": "migrations"
    }
  ],
  "r2_buckets": [
    {
      "binding": "PHOTOS",
      "bucket_name": "${R2_BUCKET_NAME:-parity-photos-staging}"
    }
  ],
  "triggers": {
    "crons": ["0 3 * * *"]
  }
}
EOF
say "Configured wrangler.jsonc with staging database and bucket."

step "Executing: npx wrangler d1 migrations apply parity-db-staging --remote"
if confirm "Apply migrations 0001 and 0002 to remote staging D1 now?"; then
  npx wrangler d1 migrations apply parity-db-staging --remote
fi
step "Schema migrations applied."

# ── Stage 5: Configure Staging Secrets ────────────────────────────────────
stage "Configure Secrets (CRON_SECRET & JWT_SECRET)"
say "Setting dedicated CRON_SECRET and JWT_SECRET for fail-closed security (SEC-04)."
ask_secret JWT_SECRET "Enter a strong random JWT_SECRET for staging:"
ask_secret CRON_SECRET "Enter a strong random CRON_SECRET for staging maintenance:"
write_env JWT_SECRET "$JWT_SECRET"
write_env CRON_SECRET "$CRON_SECRET"

if confirm "Push secrets to Cloudflare staging worker via wrangler secret put?"; then
  printf '%s' "$JWT_SECRET" | npx wrangler secret put JWT_SECRET --name parity-app-staging || true
  printf '%s' "$CRON_SECRET" | npx wrangler secret put CRON_SECRET --name parity-app-staging || true
fi

# ── Stage 6: Deployment & Smoke Test Verification ─────────────────────────
stage "Deploy & Staging Smoke Tests"
say "Deploying application to staging and recording audit trail."
step "Build and deploy to staging worker..."
if confirm "Deploy worker to staging now?"; then
  export WORKER_NAME="parity-app-staging"
  export D1_DATABASE_ID="${D1_DATABASE_ID}"
  export R2_BUCKET_NAME="${R2_BUCKET_NAME:-parity-photos-staging}"
  
  if ! npx cf auth whoami >/dev/null 2>&1; then
    step "Cloudflare CLI (cf) requires login..."
    npx cf auth login
  fi

  step "Executing deploy via Cloudflare CLI..."
  npm run deploy
fi

say "Staging verification test options:"
step "1. Test maintenance endpoint: curl -X POST -H 'X-Cron-Key: <CRON_SECRET>' https://<staging-worker>/api/maintenance/reconcile"
step "2. Check scheduled cron triggers in Cloudflare Dashboard"
step "3. Verify isolation from production data"

pause "Press Enter after smoke testing is verified"

finish
}

run_wizard "$@"; exit
